(function(root){'use strict';const box=document.createElement('section');box.className='employee-play-card';box.hidden=true;const title=document.createElement('h3');title.textContent='本人造型試用';const note=document.createElement('p');note.textContent='只切換本頁顯示，不改已保存的裝備、金幣或進度。選購其他髮型後會沿用換裝。';box.append(title,note);const buttons=[];for(const [value,label]of[['photo','新版本人造型'],['equipped','沿用目前換裝'],['legacy','原本角色']]){const b=document.createElement('button');b.type='button';b.className='text-button';b.textContent=label;b.onclick=()=>root.CozySharedPortrait.setDisplay(value);box.append(b);buttons.push([b,value]);}document.querySelector('#player-area')?.prepend(box);const timer=setInterval(()=>{const m=root.CozySharedPortrait.local;box.hidden=!m?.portraitKey;for(const[b,v]of buttons)b.setAttribute('aria-pressed',String(m?.mode===v));},700);addEventListener('pagehide',()=>clearInterval(timer),{once:true});})(window);
